import { expect, test, uniqueName } from "../../fixtures";

const EXAMPLES = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
] as const;

const FLAG = "insurance_expiring_soon";

function isoDateInDays(days: number): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

for (const { days, include } of EXAMPLES) {
  test(
    `insurance expiring in ${days} days ${include ? "includes" : "does not include"} the expiring-soon flag`,
    { tag: "@REV-08" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV08 Vendor"),
          category: "services",
          contact_email: `rev08-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();

      const expiry = isoDateInDays(days);
      const documentResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(`Certificate of Insurance\nExpires: ${expiry}\n`),
          },
        },
      });
      expect(documentResponse.status()).toBe(201);
      const document = await documentResponse.json();

      // Wait for extraction to finish before reading flags.
      let status = document.status as string;
      for (let attempt = 0; attempt < 60 && status === "processing"; attempt++) {
        await new Promise((resolve) => setTimeout(resolve, 500));
        const poll = await member.get(`/api/documents/${document.id}`);
        expect(poll.status()).toBe(200);
        status = (await poll.json()).status;
      }
      expect(status).toBe("extracted");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status()).toBe(200);
      const body = await response.json();
      if (include) {
        expect(body.flags).toContain(FLAG);
      } else {
        expect(body.flags).not.toContain(FLAG);
      }
    },
  );
}
